(function(root){root.CKSH_UNIFIED_BANK_114_CHINESE={"meta":{"id":"cksh-114-1-1-g1-chinese","subject":"chinese","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"variant":"國綜","sourceType":"school_official","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","expected_question_count":34,"raw_layer":"school_pdf_paraphrase_review_required","academicYear":114,"paperUrl":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf"},"groups":[{"id":"cksh-114-1-1-g1-chinese-q10-11","question_numbers":[10,11],"title":"父母婚姻的日常修行","stem":"薛仁明談父母的婚姻（平台依校方改寫文章整理）：作者認為家庭是人學習相處和成長的地方；物質與個人主義容易使家庭關係空洞。父母經媒妁成婚，個性及口味不同，早年曾爭執，隨年月相互理解而少有真正衝突。母親愛吃辣，卻因家庭長年不吃辣而平靜地調整習慣，沒有表現委屈。作者由此體會婚姻所說的「修行」是放下個人執著、如實體察伴侶，讓彼此都好；婚姻重在日復一日的包容和磨合，勝過只求戀愛時的詩情畫意。","source_page":3,"source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","display_mode":"shared_context","depends_on":[],"rights_status":"metadata_only_pending_rights","context_delivery":"school_pdf_reference","review_flags":["group_context_paraphrase_needs_review"]},{"id":"cksh-114-1-1-g1-chinese-q12-13","question_numbers":[12,13],"title":"師說：從師態度的對比","stem":"第三段\n嗟乎！師道之不傳也久矣！欲人之無惑也難矣！古之聖人，其出\n人也遠矣，猶且從師而問焉；今之眾人，其下聖人也亦遠矣，而恥學\n於師。是故聖益聖，愚益愚。聖人之所以為聖，愚人之所以為愚，其\n皆出於此乎？\n第四段\n愛其子，擇師而教之，於其身也，則恥師焉，惑矣！彼童子之\n師，授之書而習其句讀者，非吾所謂傳其道、解其惑者也。句讀之不\n知，惑之不解，或師焉，或不焉，小學而大遺，吾未見其明也。\n第五段\n巫、醫、樂師、百工之人，不恥相師。士大夫之族，曰師曰弟子\n云者，則群聚而笑之。問之，則曰：「彼與彼年相若也，道相似\n也。」位卑則足羞，官盛則近諛。嗚呼！師道之不復可知矣。巫、\n醫、樂師、百工之人，君子不齒，今其智乃反不能及，其可怪也歟！","source_page":4,"source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","display_mode":"shared_context","depends_on":[],"rights_status":"public_domain_official_layout","context_delivery":"school_pdf_reference","review_flags":["group_context_paraphrase_needs_review"]},{"id":"cksh-114-1-1-g1-chinese-q14-15","question_numbers":[14,15],"title":"師說：擇師標準","stem":"甲\n古之學者必有師。師者，所以傳道、受業、解惑也。人非生而知之者，孰能無\n惑？惑而不從師，其為惑也終不解矣！生乎吾前，其聞道也，固先乎吾，吾從而師\n之；生乎吾後，其聞道也，亦先乎吾，吾從而師之。吾師道也，夫庸知其年之先後生\n於吾乎？是故無貴、無賤、無長、無少，道之所存，師之所存也。\n乙\n聖人無常師：孔子師郯子、萇弘、師襄、老聃。郯子之徒，其賢不及孔子。孔子\n曰：「三人行，則必有我師」。是故弟子不必不如師，師不必賢於弟子。聞道有先\n後，術業有專攻，如是而已。","source_page":4,"source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","display_mode":"shared_context","depends_on":[],"rights_status":"public_domain_official_layout","context_delivery":"school_pdf_reference","review_flags":["group_context_paraphrase_needs_review"]},{"id":"cksh-114-1-1-g1-chinese-q16-18","question_numbers":[16,17,18],"title":"世說新語：王子猷兩事","stem":"甲\n王子猷出都，尚在渚下。舊聞桓子野善吹笛，而不相識。遇桓於岸上過，王在船\n中，客有識之者云：「是桓子野。」王便令人與相聞，云：「聞君善吹笛，試為我一\n奏。」桓時已貴顯，素聞王名，即便迴下車，踞胡床，為作三調。弄畢，便上車去，\n客主不交一言。（《世說新語．任誕》）\n乙\n王子猷居山陰，夜大雪，眠覺，開室，命酌酒，四望皎然。因起仿偟，詠左思\n〈招隱〉詩，忽憶戴安道。時戴在剡，即便夜乘小船就之。經宿方至，造門不前而\n返。人問其故，王曰：「吾本乘興而行，興盡而返，何必見戴？」（《世說新語．任\n誕》）","source_page":4,"source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","display_mode":"shared_context","depends_on":[],"rights_status":"public_domain_official_layout","context_delivery":"school_pdf_reference","review_flags":["group_context_paraphrase_needs_review"]},{"id":"cksh-114-1-1-g1-chinese-q19-20","question_numbers":[19,20],"title":"義鼠與鬼頭刀","stem":"甲\n楊天一言：「見二鼠出，其一為蛇所吞；其一瞪目如椒，似甚恨怒，然遙望不敢\n前。蛇果腹，蜿蜒入穴，方將過半，鼠奔來，力嚼其尾。蛇怒，退身出。鼠故便捷，\n欻然遁去，蛇追不及而返。及入穴，鼠又來，嚼如前狀。蛇入則來，蛇出則往，如是\n者久。蛇出，吐死鼠於地上。鼠來嗅之，啾啾如悼息，啣之而去。」友人張歷友為作\n〈義鼠行〉。（蒲松齡《聊齋誌異》）\n乙〈鬼頭刀〉（平台依原文整理）：漁人釣上一隻母鬼頭刀，原先把拉扯視為搏鬥；另有一隻未上鉤的公魚卻始終緊靠母魚，隨她躍起落下。漁人看見公魚陪伴的情景，想到魚有自己的情感，不該把人類陸地上的鬥爭習慣帶到海洋，於是漸漸鬆手，最後魚鉤折斷。甲文為楊天一轉述，兩隻鼠中一隻被蛇吞下，另一隻伺機咬蛇尾，終使蛇吐出已死同伴。","source_page":5,"source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","display_mode":"shared_context","depends_on":[],"rights_status":"metadata_only_pending_rights","context_delivery":"school_pdf_reference","review_flags":["group_context_paraphrase_needs_review"]},{"id":"cksh-114-1-1-g1-chinese-q31-32","question_numbers":[31,32],"title":"現代詩創作：鍊金與馭劍","stem":"甲〈詩與鍊金術〉、乙〈一個詩人的自覺與反省〉（平台依校方改寫文章整理）：甲把詩人比作鍊金師，認為詩人需有強大意志，不接受平庸廉價的日常語言停留在原貌，而將它加工成有情緒與意義的珍貴詩作；材料仍是生活中的普通語言。乙說現代詩字數少不等於思想少，不押韻也需注意字詞節奏；故意扭曲文字不等於創新，單一驚人的意象也不足以成就完整詩篇。詩人需有自覺力與反省力，像馭劍者追求身劍合一，讓意象與主景、主境和周邊布景相融，成為有機整體。","source_page":8,"source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","display_mode":"shared_context","depends_on":[],"rights_status":"metadata_only_pending_rights","context_delivery":"school_pdf_reference","review_flags":["group_context_paraphrase_needs_review"]},{"id":"cksh-114-1-1-g1-chinese-q33-34","question_numbers":[33,34],"title":"傷仲永與逆旅小子","stem":"甲\n金谿民方仲永，世隸耕。仲永生五年，未嘗識書具，忽啼求之。父異焉，借旁近\n與之，即書詩四句，並自為其名。其詩以養父母、收族為意，傳一鄉秀才觀之。自是\n指物作詩立就，其文理皆有可觀者。邑人奇之，稍稍賓客其父，或以錢幣乞之。父利\n其然也，日扳仲永環謁於邑人，不使學。\n予聞之也久。明道中，從先人還家，於舅家見之，十二三矣。令作詩，不能稱前\n時之聞。又七年，還自揚州，復到舅家，問焉。曰：「泯然眾人矣！」\n王子日：「仲永之通悟，受之天也。其受之天也，賢於材人遠矣。卒之為眾人，\n則其受於人者不至也。彼其受之天也，如此其賢也，不受之人，且為眾人；今夫不受\n之天，固眾人，又不受之人，得為眾人而已邪？」（王安石〈傷仲永〉）\n乙\n戊戌秋九月，余歸自塞上，宿石槽。逆旅小子形苦羸，敝\n布單衣，不襪不履，而主人撻擊之甚猛，泣甚悲。叩之東西\n家，曰：「是其兄之孤也。有田一區，畜產什器粗具，恐孺子\n長而與之分，故不恤其寒飢而苦役之；夜則閉之戶外。嚴風\n起，弗活矣。」余至京師，再書告京兆尹，宜檄縣捕詰，俾鄉鄰保任而後釋之。\n逾歲四月，復過此里。人曰：「孺子果以是冬死，而某亦暴死，其妻子、田宅、\n畜物皆為他人有矣。」叩以：「吏曾呵詰乎？」則未也。（節錄自方苞〈逆旅小\n子〉）\n詞注：羸＝瘦弱；逆旅＝旅店；檄＝發公文；呵詰＝斥責盤問。","source_page":9,"source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","display_mode":"shared_context","depends_on":[],"rights_status":"public_domain_official_layout","context_delivery":"school_pdf_reference","review_flags":["group_context_paraphrase_needs_review"]}],"questions":[{"id":"cksh-114-1-1-g1-chinese-q01","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":1,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":1,"source_pages":[1],"group_id":null,"stem":"下列各組「」內的字，讀音完全不同的是：","options":["「溯」及既往╱「朔」風冷冽╱木雕泥「塑」","「攙」扶前行╱手持長「鑱」／「讒」言可畏","「殫」精竭慮╱過勿「憚」改╱「簞」瓢屢空","龍「蟠」虎踞╱鬢髮「皤」然╱「幡」然悔悟"],"answer":{"index":3},"printed_answer":"D","answer_match":true,"primary_unit":"字音辨識","skill_tags":["字音辨識"],"explanation":{"schema":"explanation-v2","concept":"字音辨識","key_insight":"逐字標注音與聲調，再比較同組三字。","reasoning":"D 的蟠、皤、幡依序讀 ㄆㄢˊ、ㄆㄛˊ、ㄈㄢ，聲母與韻母均不盡相同。A 的溯與塑同讀 ㄙㄨˋ；B 的鑱與讒同讀 ㄔㄢˊ；C 的殫與簞同讀 ㄉㄢ，故只有 D 三字全異。","solution":"D 的蟠、皤、幡依序讀 ㄆㄢˊ、ㄆㄛˊ、ㄈㄢ，聲母與韻母均不盡相同。A 的溯與塑同讀 ㄙㄨˋ；B 的鑱與讒同讀 ㄔㄢˊ；C 的殫與簞同讀 ㄉㄢ，故只有 D 三字全異。","common_errors":"同字旁不保證同音；注意題目要求三字兩兩不同。","option_analysis":["溯、塑同音。","鑱、讒同音。","殫、簞同音。","蟠、皤、幡三字讀音不同。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q02","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":2,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":["https://dict.revised.moe.edu.tw/dictView.jsp?ID=159425&la=0&powerMode=0","https://dict.revised.moe.edu.tw/dictView.jsp?ID=158807&la=0&powerMode=0"],"source_page":1,"source_pages":[1],"group_id":null,"stem":"下列文句，完全沒有錯別字的是：","options":["花蓮堰塞湖洪災現場令人不忍猝睹，需要更多人力、物資進駐救災","巴勒斯坦建國牽動地緣政治，國際間輿論立場各有以偏概全的盲點","電子煙的氾濫，加速毒品滲入校園，危害學子健康，令人痛心棘首","供電穩定對科技業的重要性無庸至疑，致使核三重啟成為全民議題"],"answer":{"index":1},"printed_answer":"B","answer_match":true,"primary_unit":"錯別字","skill_tags":["錯別字"],"explanation":{"schema":"explanation-v2","concept":"錯別字","key_insight":"逐句找固定詞語的正確寫法。","reasoning":"B 的「以偏概全」字形正確；A 的「不忍猝睹」應作「不忍卒睹」，C 的「痛心棘首」應作「痛心疾首」，D 的「無庸至疑」須將「至」改為「置」，因此選 B。教育部辭典兼收「無庸置疑」與「毋庸置疑」，本題不能把「無」單獨判為錯字。","solution":"B 的「以偏概全」字形正確；A 的「不忍猝睹」應作「不忍卒睹」，C 的「痛心棘首」應作「痛心疾首」，D 的「無庸至疑」須將「至」改為「置」，因此選 B。教育部辭典兼收「無庸置疑」與「毋庸置疑」，本題不能把「無」單獨判為錯字。","common_errors":"不要混淆「猝／卒」、「棘／疾」、「至／置」；「無庸」也是詞典收錄的寫法。","option_analysis":["猝應改卒。","沒有錯別字。","棘應改疾。","至應改置，無庸本身可用。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q03","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":3,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":1,"source_pages":[1],"group_id":null,"stem":"下列是一段古文，依據文意，甲、乙、丙、丁排列順序最適當的是：\n種樹之樂多端，而其不便於雅人者亦有一節：枝葉繁冗，不漏月光。隔嬋娟而不\n使見者，\n甲、留一線之餘天，以待月輪出沒\n乙、然匪樹木無心，人無心耳\n丙、使於種植之初，預防及此\n丁、此其無心之過，不足責也\n則晝夜均受其利矣。（李漁《聞情偶寄•柳》）","options":["丁乙丙甲","乙丙丁甲","丙甲丁乙","甲丁丙乙"],"answer":{"index":0},"printed_answer":"A","answer_match":true,"primary_unit":"文句排序","skill_tags":["文句排序"],"explanation":{"schema":"explanation-v2","concept":"文句排序","key_insight":"找承上啟下的指示詞與轉折詞。","reasoning":"先承接樹木遮月的情況，用丁「此其無心之過」指前述不便；接乙「然」轉折指出其實可由人預防；丙「使於種植之初」提出條件；甲「留一線」接具體做法，末句「則晝夜均受其利」收束，所以丁乙丙甲，選 A。","solution":"先承接樹木遮月的情況，用丁「此其無心之過」指前述不便；接乙「然」轉折指出其實可由人預防；丙「使於種植之初」提出條件；甲「留一線」接具體做法，末句「則晝夜均受其利」收束，所以丁乙丙甲，選 A。","common_errors":"乙的「然」不能直接作全段開頭；末句「則」必須有前面的假設。","option_analysis":["丁乙丙甲，承接、轉折、條件、做法完整。","先轉折才指示「此」，順序不順。","把預防置於批評之前，文脈倒置。","從做法開頭，缺少承接。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q04","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":4,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":1,"source_pages":[1],"group_id":null,"stem":"閱讀三首詩的線索，判斷三個空格依序應填什麼：甲寫他人都安睡，唯獨自己的心如暴風中的小船，無法停泊；詩題應概括此狀態。乙寫駱駝隊遠行沙漠，疲憊時不在意能否夢見沙漠中的水草之地。丙寫某一感官承接他人的言語稱讚或咒罵；臭味則屬於鼻子的事。依甲的詩題、乙的目的地及丙的感官名稱選擇。","options":["靈感／天國／耳朵","靈感／綠洲／鼻子","失眠／綠洲／耳朵","失眠／天國／鼻子"],"answer":{"index":2},"printed_answer":"C","answer_match":true,"primary_unit":"詩句語境","skill_tags":["詩句語境"],"explanation":{"schema":"explanation-v2","concept":"詩句語境","key_insight":"分別依失眠、沙漠休息及五官功能定空格。","reasoning":"甲的「全部停泊在睡眠港灣／只有我」對比可知題名是失眠；乙有駱駝與沙漠，旅行者期待綠洲；丙末句把臭歸給鼻子，所以被詩人寫成無力置喙的是耳朵。依序失眠、綠洲、耳朵，選 C。","solution":"甲的「全部停泊在睡眠港灣／只有我」對比可知題名是失眠；乙有駱駝與沙漠，旅行者期待綠洲；丙末句把臭歸給鼻子，所以被詩人寫成無力置喙的是耳朵。依序失眠、綠洲、耳朵，選 C。","common_errors":"不要只靠乙的「夢見」猜天國，仍須看沙漠脈絡。","option_analysis":["甲非靈感，乙非天國。","甲非靈感，丙非鼻子。","三空都與文中線索吻合。","乙的沙漠目的地不是天國。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","modern_text_rights_review_required"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"platform_context_with_original_options","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q05","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":5,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":2,"source_pages":[2],"group_id":null,"stem":"炭治郎、禰豆子、善逸和伊之助被困在文學島上的鬼滅迷宮，發現地上散落寫著\n不同文句的紙牌。文學島規定必須找到四張有使用同一種修辭技巧的紙牌，才能\n打開迷宮之門，以下依四人找到的紙牌判斷，能順利逃出迷宮的是：","options":["炭治郎\n◆那河畔的金柳，／是夕陽中的新娘\n◆沉默是今晚的康橋\n◆一個個餌鉤沉下水面，就像沉下一個個倒懸的問號\n◆吾師肺肝，皆鐵石所鑄造也","禰豆子\n▲悄悄是別離的笙簫\n▲庸奴！此何地也，而汝來前\n▲令二人蹲踞而背倚之，漏鼓移則番代\n▲黃絹，色絲也，於字為「絕」","善逸\n★輭泥上的青荇，／油油的在水底招搖\n★引擎再度恢復急迫的節奏，一下下沉痛的撞擊我心\n★時空似乎凍結住了，就等候斷裂的一聲巨響\n★滿載一船星輝，／在星輝斑斕裡放歌","伊之助\n■句讀之不知，惑之不解，或師焉，或不焉\n■我才不及卿，乃覺三十里\n■汝復輕身而昧大義，天下事誰可支拄者\n■吾本乘興而行，興盡而返，何必見戴"],"answer":{"index":2},"printed_answer":"C","answer_match":true,"primary_unit":"修辭辨析","skill_tags":["修辭辨析"],"explanation":{"schema":"explanation-v2","concept":"修辭辨析","key_insight":"逐張對照四句的表現手法，找同類而非只看一句。","reasoning":"校方卷面選 C。善逸組把青荇寫成招搖、引擎寫出急迫節奏，時空「凍結」與星輝「滿載」也把景象轉作可感動作或實物；其餘三組混有譬喻、直接敘事或倒裝，不能將四張全歸同一類。本題各句修辭邊界仍需對照校方圖式複核。","solution":"校方卷面選 C。善逸組把青荇寫成招搖、引擎寫出急迫節奏，時空「凍結」與星輝「滿載」也把景象轉作可感動作或實物；其餘三組混有譬喻、直接敘事或倒裝，不能將四張全歸同一類。本題各句修辭邊界仍需對照校方圖式複核。","common_errors":"A 雖有「像」的譬喻，不能只憑其中一句認定整組。","option_analysis":["有新娘、問號等譬喻，也有其他形式。","夾雜直接敘事和拆字，並非同一修辭。","校方標 C；四句判法尚待人工核對。","多是敘事與文言句法，不是四個同類修辭。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","modern_text_rights_review_required","visual_layout_review_required","explanation_inference_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q06","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":6,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":2,"source_pages":[2],"group_id":null,"stem":"依據下文，說明最適當的是：\n世人畫韓退之，小面而美髯，著紗帽。此乃江南韓熙載耳，尚有當時所畫，題\n誌甚明。熙載諡文靖，江南人謂之韓文公，因此遂謬以為退之。退之肥而寡髯。\n元豐中，以退之從享文宣王廟，郡縣所畫，皆是熙載，後世不復可辨，退之遂為\n熙載矣。\n（沈括《夢溪筆談》\n）","options":["韓退之的畫像在宋代元豐年間才開始出現，故無從辨識","韓熙載的畫像因為題誌不明，導致後人誤以為是韓退之","韓退之的真實樣貌是「小面而美髯」，與韓熙載極為相似","江南人習慣尊稱韓熙載為「韓文公」，間接造成圖像混淆"],"answer":{"index":3},"printed_answer":"D","answer_match":true,"primary_unit":"史料因果","skill_tags":["史料因果"],"explanation":{"schema":"explanation-v2","concept":"史料因果","key_insight":"抓畫像誤認的兩個關鍵：別名相同與先存圖像。","reasoning":"文中明說韓熙載畫像原有明確題誌，江南人卻稱韓熙載「韓文公」；後世把畫像誤作韓退之，且韓退之實為肥而寡髯。造成混淆的間接因素正是同一稱號，選 D。","solution":"文中明說韓熙載畫像原有明確題誌，江南人卻稱韓熙載「韓文公」；後世把畫像誤作韓退之，且韓退之實為肥而寡髯。造成混淆的間接因素正是同一稱號，選 D。","common_errors":"不要把「題誌甚明」看成題誌不清。","option_analysis":["未說元豐才首次畫韓退之。","題誌其實清楚。","小面美髯是韓熙載形象。","同稱韓文公造成誤認。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q07","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":7,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":2,"source_pages":[2],"group_id":null,"stem":"偏鄉教師荒，依下列招募媒體比較資料，哪項推論最適當？\n媒體｜費用｜年齡｜優勢｜限制\n紙本傳單｜3～5萬｜35～50歲｜針對老師｜不易普及\n網路媒體｜10萬以下｜可調整｜即時互動、成本不高、可追蹤成效｜僅針對上網人口\n公車廣告｜10～30萬｜35～50歲｜高頻率出現｜區域、創意受限\n廣播節目｜10～30萬｜50～65歲｜聽眾可同時做事｜訊息轉瞬即逝、廣告時間短","options":["紙本傳單、網路媒體、公車廣告三者均會受到空間距離的限制","若需尋求已退休老師協助，紙本傳單為最有效直接的宣傳方式","如想了解宣傳成效，在媒體類型的考量上是廣播優於網路媒體","若經費有限，則在媒體類型的考量上是網路媒體優於公車廣告"],"answer":{"index":3},"printed_answer":"D","answer_match":true,"primary_unit":"圖表比較","skill_tags":["圖表比較"],"explanation":{"schema":"explanation-v2","concept":"圖表比較","key_insight":"用宣傳預算、對象與可追蹤性逐項交叉核對。","reasoning":"紙本傳單費用約三至五萬，網路媒體在十萬以下且可追蹤成效，公車廣告約十至三十萬；預算有限時網路相對公車較可行，選 D。A 把網路宣傳說成與地方廣告一樣受距離限制；B 的退休族群偏五十至六十五歲，紙本表列三十五至五十歲；C 把網路「可追蹤成效」誤給廣播。","solution":"紙本傳單費用約三至五萬，網路媒體在十萬以下且可追蹤成效，公車廣告約十至三十萬；預算有限時網路相對公車較可行，選 D。A 把網路宣傳說成與地方廣告一樣受距離限制；B 的退休族群偏五十至六十五歲，紙本表列三十五至五十歲；C 把網路「可追蹤成效」誤給廣播。","common_errors":"「十萬以下」不是保證低於所有紙本費用，D 只比較網路與公車。","option_analysis":["網路可跨地區，不能一概說受空間距離限制。","紙本主要對象年齡不符退休師資。","可追蹤成效的是網路。","網路費用上限低於公車區間。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","visual_layout_review_required"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"platform_context_with_original_options","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q08","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":8,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":2,"source_pages":[2,3],"group_id":null,"stem":"依據下文，關於白居易、元微之二人的友情，敘述最適當的是：\n四月十日夜，樂天白：\n人生幾何？離闊如此！況以膠漆之心，置於胡、越之身；進不得相合，退不能\n相忘，牽攣乖隔，各欲白首。\n僕初到潯陽時，有熊孺登來，得足下前年病甚時一札：上報疾狀，次敘病心，\n終論平生交分。且云：「危惙之際，不暇及他，惟收數帙文章，封題其上，曰：\n『他日送達白二十二郎，便請以代書。』」悲哉！微之於我也，其若是乎！又睹\n所寄聞僕左降詩云：「殘燈無焰影幢幢，此夕聞君謫九江。垂死病中驚坐起，闇\n風吹雨入寒窗。」此句他人尚不可聞，況僕心哉！至今每吟，猶惻惻耳。（節錄\n自白居易〈與元微之書〉）\n\n3","options":["「以膠漆之心，置於胡、越之身」凸顯元、白二人雖南北阻隔，卻關心永在","「得足下前年病甚時一札」可知元微之於病中不忘摯友，託人贈書予白居易","「悲哉！微之於我也，其若是乎！」乃白居易自愧元微之因受己身牽累而病","「此句他人尚不可聞」指元微之視白居易為作品的第一讀者，認定其為摯友"],"answer":{"index":0},"printed_answer":"A","answer_match":true,"primary_unit":"文言情意","skill_tags":["文言情意"],"explanation":{"schema":"explanation-v2","concept":"文言情意","key_insight":"分清寄信的人、寄信內容與兩人距離。","reasoning":"白居易說「膠漆之心」像黏合，卻「胡越之身」遠隔；人不能相見也不能相忘，所以 A 描述兩人友誼切合。病中一札是元微之寫給白氏；「悲哉」感念友誼並非自責害病；「此句」令白氏感動，不是認定他為第一讀者。","solution":"白居易說「膠漆之心」像黏合，卻「胡越之身」遠隔；人不能相見也不能相忘，所以 A 描述兩人友誼切合。病中一札是元微之寫給白氏；「悲哉」感念友誼並非自責害病；「此句」令白氏感動，不是認定他為第一讀者。","common_errors":"收到病中書信，不等於元微之親自到訪。","option_analysis":["心近而身遠，與全文一致。","曲解病中寄書為託人贈書。","「悲哉」是感動哀傷，非致病之愧。","未說白氏是第一讀者。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q09","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":9,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":3,"source_pages":[3],"group_id":null,"stem":"下列〈左忠毅公逸事〉一文中的兩段文字，解讀最不適當的是：\n甲\n先君子嘗言：鄉先輩左忠毅公視學京畿。一日，風雪嚴寒，從數騎出，微行，\n入古寺。廡下一生伏案臥，文方成草。公閱畢，即解貂覆生，為掩戶。叩之寺\n僧，則史公可法也。及試，吏呼名，至史公，公瞿然注視。呈卷，即面署第一。\n召入，使拜夫人，曰：「吾諸兒碌碌，他日繼吾志事，惟此生耳！」\n乙\n崇禎末，流賊張獻忠出沒蘄、黃、潛、桐間，史公以鳳廬道奉檄守禦。①每有\n警，輒數月不就寢，②使將士更休，而自坐幄幕外，擇健卒十人，令二人蹲踞而\n背倚之，漏鼓移則番代。③每寒夜起立，振衣裳，甲上冰霜迸落，鏗然有聲。或\n勸以少休，公曰：「④吾上恐負朝廷，下恐愧吾師也。」","options":["甲文「廡下一生伏案臥，文方成草」呼應乙文①，以此情狀預示史公日後必為國事勞瘁不眠","甲文「公閱畢，即解貂覆生，為掩戶」呼應乙文②，足見師生二人皆有愛護後輩或部屬之心","甲文「風雪嚴寒，從數騎出，微行，入古寺」呼應乙文③，說明師生皆不畏風雪，盡忠職守","甲文「吾諸兒碌碌，他日繼吾志事，惟此生耳」呼應乙文④，以此說明師生二人相繼之志事"],"answer":{"index":0},"printed_answer":"A","answer_match":true,"primary_unit":"文本呼應","skill_tags":["文本呼應"],"explanation":{"schema":"explanation-v2","concept":"文本呼應","key_insight":"對照前後故事具體動作，排除過度預言。","reasoning":"甲寫史可法在古寺伏案寫文而睡，乙①寫他任官遇警長期不睡；前者是當下疲累，不能據此說作者預言後日必為國事勞瘁不眠，因此 A 最不適當。乙②體恤將士、③甲衣結霜、④不負師志，與其餘對照方向相應。","solution":"甲寫史可法在古寺伏案寫文而睡，乙①寫他任官遇警長期不睡；前者是當下疲累，不能據此說作者預言後日必為國事勞瘁不眠，因此 A 最不適當。乙②體恤將士、③甲衣結霜、④不負師志，與其餘對照方向相應。","common_errors":"同有「睡」字不等於具備預示未來的敘事證據。","option_analysis":["伏案而睡不預示未來不眠。","兩人都展現照護他人的心。","兩處風寒呼應盡職。","史公明言不願愧對其師。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q10","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":10,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":3,"source_pages":[3],"group_id":"cksh-114-1-1-g1-chinese-q10-11","stem":"作者以父母的婚姻為例，闡述中國式婚姻的核心精神。下列敘述不符合作者看法的是：","options":["專注追尋理想，保持獨立個體性","練習感知與包容對方，學習共好","學會平和放下個人的習氣與執著","在日常瑣碎中，彼此磨合與成長"],"answer":{"index":0},"printed_answer":"A","answer_match":true,"primary_unit":"論點理解","skill_tags":["論點理解"],"explanation":{"schema":"explanation-v2","concept":"論點理解","key_insight":"分清作者稱許的磨合與選項偏重個體的主張。","reasoning":"文章由父母爭執漸少、母親放下習氣及父母彼此相知，推出婚姻是日常修行；B、C、D 均可從包容、放下、磨合找到支撐。A 的「專注理想、保持獨立個體性」偏離本文強調的相互感知與共好，因此選 A。","solution":"文章由父母爭執漸少、母親放下習氣及父母彼此相知，推出婚姻是日常修行；B、C、D 均可從包容、放下、磨合找到支撐。A 的「專注理想、保持獨立個體性」偏離本文強調的相互感知與共好，因此選 A。","common_errors":"題目問「不符合」，勿把日常修行誤寫成自我犧牲。","option_analysis":["偏重單獨個體理想，缺少相互修行。","感知與包容符合。","放下習氣符合。","日常磨合符合。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q11","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":11,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":3,"source_pages":[3],"group_id":"cksh-114-1-1-g1-chinese-q10-11","stem":"根據本文的觀點，下列最符合「從詩情到修行」轉變過程的是：","options":["從無所不談的甜蜜到保持距離的美感","從為愛奮不顧身到為了生活反覆叮嚀","從著重外在的浪漫到關注內在的沉穩","從盡全力配合對方到堅持自己的原則"],"answer":{"index":2},"printed_answer":"C","answer_match":true,"primary_unit":"譬喻轉換","skill_tags":["譬喻轉換"],"explanation":{"schema":"explanation-v2","concept":"譬喻轉換","key_insight":"把詩情、浪漫與修行、內在成長配對。","reasoning":"作者把婚姻從浪漫想像轉為日復一日的磨合，故「從著重外在浪漫到關注內在沉穩」最合，選 C。A 的保持距離、B 的反覆叮嚀都未呈現核心修行；D 的固守己見正與放下執著相反。","solution":"作者把婚姻從浪漫想像轉為日復一日的磨合，故「從著重外在浪漫到關注內在沉穩」最合，選 C。A 的保持距離、B 的反覆叮嚀都未呈現核心修行；D 的固守己見正與放下執著相反。","common_errors":"修行不是只替對方做事，而是彼此真正理解。","option_analysis":["距離不是相知相容。","叮嚀只是生活表象。","外在浪漫到內在修養符合。","固執己見違背放下習氣。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q12","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":12,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":4,"source_pages":[4],"group_id":"cksh-114-1-1-g1-chinese-q12-13","stem":"下列文句說明最適當的是：","options":["第三段「聖人之所以為聖，愚人之所以為愚，其皆出於此乎？」句中「此」為代名詞，指「恥學於師」","第四段「小學而大遺，吾未見其明也。」句中的「小學」是指句讀之學；「大遺」則指道業的疑惑","第三段與第五段的「師道」均指從師問學的道理，第五段的「不恥」與「不齒」則為同義詞語的抽換","第五段「巫、醫、樂師、百工之人，君子不齒，今其智乃反不能及，其可怪也歟！」表達委婉的勸說"],"answer":{"index":1},"printed_answer":"B","answer_match":true,"primary_unit":"師說字義","skill_tags":["師說字義"],"explanation":{"schema":"explanation-v2","concept":"師說字義","key_insight":"先辨「小學／大遺」，再看兩種師道與不恥、不齒。","reasoning":"韓愈說教童子句讀只是較小的學問，解人生道業之惑才是大的；只顧句讀而放掉傳道解惑，故 B。A 把「此」限成今人恥師，漏掉古人從師與今人恥師的對照；C 不恥是以為不羞，不齒是不屑同列；D 是感嘆譏諷而非委婉。","solution":"韓愈說教童子句讀只是較小的學問，解人生道業之惑才是大的；只顧句讀而放掉傳道解惑，故 B。A 把「此」限成今人恥師，漏掉古人從師與今人恥師的對照；C 不恥是以為不羞，不齒是不屑同列；D 是感嘆譏諷而非委婉。","common_errors":"同字「恥／齒」形近但語義不同。","option_analysis":["「此」關乎從師態度的比較。","句讀小學、道惑大遺。","不恥與不齒意思不同。","末句是感嘆與批評。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q13","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":13,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":4,"source_pages":[4],"group_id":"cksh-114-1-1-g1-chinese-q12-13","stem":"行文之中運用對比手法，可使說理更加鮮明有力，下列關於〈師說〉文中的對比運用，說明最適當的是：","options":["第三段以「古之聖人」對比「今之眾人」，說明古有聖人可學，今人則無，故古今學者相差甚遠","第四段以「士大夫為子擇師」對比「於其身也則恥師」，說明父母一輩無師可學，因此勉子學習",")第五段以「巫、醫、樂師、百工之人」對比「士大夫之族」，彰顯士大夫不學，態度比不上百工","第五段以「位卑則足羞」對比「官盛則近諛」，反映唐代的階級對立嚴重，期能藉學習改變狀況"],"answer":{"index":2},"printed_answer":"C","answer_match":true,"primary_unit":"論證手法","skill_tags":["論證手法"],"explanation":{"schema":"explanation-v2","concept":"論證手法","key_insight":"辨對比兩方，再查選項是否把作者未說的原因加入。","reasoning":"第五段把巫醫樂師百工能互相學習，與士大夫見師徒便聚而笑對照；韓愈藉此批評士大夫之智反不及百工，故 C。古聖與今眾人不是「今日沒有聖人」，父母為子擇師也不是因成人無師可學，位卑／官盛只是士大夫藉口。","solution":"第五段把巫醫樂師百工能互相學習，與士大夫見師徒便聚而笑對照；韓愈藉此批評士大夫之智反不及百工，故 C。古聖與今眾人不是「今日沒有聖人」，父母為子擇師也不是因成人無師可學，位卑／官盛只是士大夫藉口。","common_errors":"對比是態度差異，不能推成唐代各階級都無法交流。","option_analysis":["古今都可以從師，並非今無聖人。","不是無師可學，而是不肯師。","百工不恥相師，士大夫反而恥學。","兩句是士大夫的推諉。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q14","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":14,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":4,"source_pages":[4],"group_id":"cksh-114-1-1-g1-chinese-q14-15","stem":"依據甲、乙二文，下列闡釋最適當的是：","options":["「吾師道也，夫庸知其年之先後生於吾乎？」→無論年少年長，皆應學習","「人非生而知之者，孰能無惑？」→以激問點出人皆有惑，故須求師解惑","「聖人無常師」→聖人啟迪後輩的教育方法並不尋常，能真正的傳道授業","「郯子之徒，其賢不及孔子。」→郯子學生的才學能力，遠遠比不上孔子"],"answer":{"index":1},"printed_answer":"B","answer_match":true,"primary_unit":"古文詮釋","skill_tags":["古文詮釋"],"explanation":{"schema":"explanation-v2","concept":"古文詮釋","key_insight":"找設問句的論證作用及代詞指涉。","reasoning":"「人非生而知之者，孰能無惑？」以反問強調人人有疑惑，接著推出必須從師求解，所以 B。A 把無論年齡的「擇師」弱化為一般學習；C 誤讀「無常師」為教學方法奇特；D 的「郯子之徒」是郯子這些人，不是郯子的學生。","solution":"「人非生而知之者，孰能無惑？」以反問強調人人有疑惑，接著推出必須從師求解，所以 B。A 把無論年齡的「擇師」弱化為一般學習；C 誤讀「無常師」為教學方法奇特；D 的「郯子之徒」是郯子這些人，不是郯子的學生。","common_errors":"「徒」在這裡是同類、這些人，非徒弟。","option_analysis":["強調師道不以年齡為限，非泛指學習。","反問導出解惑須從師。","無常師＝不固定只向一人請教。","郯子之徒非郯子的學生。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q15","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":15,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":4,"source_pages":[4],"group_id":"cksh-114-1-1-g1-chinese-q14-15","stem":"依據甲、乙二文，最符合韓愈對「學習」看法的是：","options":["智愚不同會影響學習成效，故聞道有先有後","尊重專業，因此擇師學習無需計較年齡身分","師存則道存，因此自少至長皆應精進地學習","有志竟成，只要投入學習，必然能專攻術業"],"answer":{"index":1},"printed_answer":"B","answer_match":true,"primary_unit":"從師觀念","skill_tags":["從師觀念"],"explanation":{"schema":"explanation-v2","concept":"從師觀念","key_insight":"整合「道之所存，師之所存」和「術業有專攻」。","reasoning":"甲不論長幼貴賤，只要對方聞道先於我便從師；乙又說各有專業、弟子不必永遠不如老師。因此尊重專業且不計身分年齡，選 B。智愚不是聞道先後的必然原因，文中也沒有保證用功就必能專攻。","solution":"甲不論長幼貴賤，只要對方聞道先於我便從師；乙又說各有專業、弟子不必永遠不如老師。因此尊重專業且不計身分年齡，選 B。智愚不是聞道先後的必然原因，文中也沒有保證用功就必能專攻。","common_errors":"「師不必賢於弟子」不是主張不需要老師。","option_analysis":["先後因聞道及專業，不是固定智愚。","學其所長，不計身分年齡。","題意重擇師準則，不是終生年齡義務。","文中沒有必然成功的保證。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q16","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":16,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":5,"source_pages":[5],"group_id":"cksh-114-1-1-g1-chinese-q16-18","stem":"甲、乙二文中畫底線的「云、覺、因、造」等字，依序與下列選項「」的字比較，意義相同的是：","options":["謂獄中語，乃親得之於史公「云」","我才不及卿，乃「覺」三十里","未若柳絮「因」風起","往來桐城，必躬「造」左公第"],"answer":{"index":3},"printed_answer":"D","answer_match":true,"primary_unit":"文言一字多義","skill_tags":["文言一字多義"],"explanation":{"schema":"explanation-v2","concept":"文言一字多義","key_insight":"把畫線字放回原句，逐個代入選項測義。","reasoning":"乙「造門」的造是到、拜訪；「躬造左公第」也是親自前往，故 D。甲「云」是說，「史公云」若表語助／傳聞須看原句；「眠覺」是醒來，「乃覺三十里」是相差；「因起」是於是，「因風起」是憑藉。","solution":"乙「造門」的造是到、拜訪；「躬造左公第」也是親自前往，故 D。甲「云」是說，「史公云」若表語助／傳聞須看原句；「眠覺」是醒來，「乃覺三十里」是相差；「因起」是於是，「因風起」是憑藉。","common_errors":"「覺」可以是醒、察覺或差距，不能用字形直接判同義。","option_analysis":["兩處云須依句義判斷，非此題相同者。","醒來與相差不同。","於是與憑藉不同。","造門、造第都是前往拜訪。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q17","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":17,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":5,"source_pages":[5],"group_id":"cksh-114-1-1-g1-chinese-q16-18","stem":"下列關於甲文情境的敘述，最適當的是：","options":["子猷得知對方是善吹笛的子野，旋即親自邀請子野演奏一曲","子猷和子野兩人相逢時，彼此並不相識，但皆久仰對方大名","子野感受到子猷的誠意，雖位不及子猷，仍能依禮應允吹奏","子野最終仍基於現實位階之考量，未與子猷交談，倉促離去"],"answer":{"index":1},"printed_answer":"B","answer_match":true,"primary_unit":"人物敘事","skill_tags":["人物敘事"],"explanation":{"schema":"explanation-v2","concept":"人物敘事","key_insight":"分清王子猷是否親自邀請，以及桓子野身分。","reasoning":"二人舊聞對方卻未相識，子猷由客得知岸上人是桓子野，託人請他吹笛；子野已貴顯，也素聞子猿名，為他奏三調後離開，故 B。不是子猷親邀，也不能說子野位卑；不交一言表任誕雅趣，並無現實位階動機。","solution":"二人舊聞對方卻未相識，子猷由客得知岸上人是桓子野，託人請他吹笛；子野已貴顯，也素聞子猿名，為他奏三調後離開，故 B。不是子猷親邀，也不能說子野位卑；不交一言表任誕雅趣，並無現實位階動機。","common_errors":"「客主不交一言」不等於互相不認識對方名聲。","option_analysis":["遣人相聞，非親自邀請。","不相識但久仰姓名。","子野已貴顯，未說地位較低。","未言因位階而離去。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q18","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":18,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":5,"source_pages":[5],"group_id":"cksh-114-1-1-g1-chinese-q16-18","stem":"分析甲、乙二文，下列對王子猷的形象詮釋，敘述不適當的是：","options":["「『是桓子野。』王便令人與相聞」「忽憶戴安道」→王子猷重視人情往來","「聞君善吹笛，試為我一奏」「詠左思〈招隱〉詩」→具備音樂及詩歌雅趣","「經宿方至，造門不前而返」→行事往往看重過程中的價值，而非外在目的","「客主不交一言」「興盡而返，何必見戴」→率性放達，重視自我主體意識"],"answer":{"index":0},"printed_answer":"A","answer_match":true,"primary_unit":"人物形象","skill_tags":["人物形象"],"explanation":{"schema":"explanation-v2","concept":"人物形象","key_insight":"同讀兩段故事，找共通的率性與審美。","reasoning":"王子猷聞笛即請奏，夜雪忽憶朋友便乘興前往，興盡未進門就返；重點是即興審美與率性，不是維持日常人情往來，因此選最不適當的 A。其餘的音樂詩歌、重過程及自我主體都有情節支撐。","solution":"王子猷聞笛即請奏，夜雪忽憶朋友便乘興前往，興盡未進門就返；重點是即興審美與率性，不是維持日常人情往來，因此選最不適當的 A。其餘的音樂詩歌、重過程及自我主體都有情節支撐。","common_errors":"忽憶戴安道不代表這次一定見到他。","option_analysis":["兩次均隨興而行，非社交義務。","欣賞笛聲並詠詩。","到門不入印證重過程。","不交言、興盡即返，皆率性。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q19","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":19,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":5,"source_pages":[5,6],"group_id":"cksh-114-1-1-g1-chinese-q19-20","stem":"甲文中小鼠面對同伴喪命，展開一系列的應敵策略，敘述不適當的是：","options":["避其鋒芒，伺機而動","速戰速退，靈活機動","就近躲藏，攻擊弱點","持之以恆，消磨敵勢"],"answer":{"index":2},"printed_answer":"C","answer_match":true,"primary_unit":"文言事件","skill_tags":["文言事件"],"explanation":{"schema":"explanation-v2","concept":"文言事件","key_insight":"按小鼠與蛇進出穴的先後順序重建策略。","reasoning":"小鼠先遠望不近身，待蛇半入穴才嚼尾，蛇出便逃，反覆多次迫蛇吐出同伴；可見避鋒、快攻快退與持續牽制。牠沒有就近找藏身處，所以 C 是不適當描述。","solution":"小鼠先遠望不近身，待蛇半入穴才嚼尾，蛇出便逃，反覆多次迫蛇吐出同伴；可見避鋒、快攻快退與持續牽制。牠沒有就近找藏身處，所以 C 是不適當描述。","common_errors":"蛇鑽的穴不是鼠的藏身處。","option_analysis":["等待時機。","蛇出即逃。","文本沒有鼠就近躲藏。","反覆牽制直到蛇吐出同伴。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q20","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":20,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":6,"source_pages":[6],"group_id":"cksh-114-1-1-g1-chinese-q19-20","stem":"張歷友為甲文之鼠作〈義鼠行〉，廖鴻基為兩隻鬼頭刀寫下乙文。大自然中萬物有情，觸動人類深層意識。下列關於二文的說明，敘述最適當的是：","options":["二文皆為作者親眼所見，故能記錄事件經過","二文中動物皆能「以小博大」成功解救同伴","甲文強調戰術與機智的陳述，肯定萬物之靈的人類更能行義為善","乙文側重情感與忠誠的敘寫，反思人類本位慾望及對自然的態度"],"answer":{"index":3},"printed_answer":"D","answer_match":true,"primary_unit":"跨文本比較","skill_tags":["跨文本比較"],"explanation":{"schema":"explanation-v2","concept":"跨文本比較","key_insight":"分清見聞來源、救援結果與作者反思。","reasoning":"甲由楊天一轉述，鼠最後取回同伴屍體；乙是敘事者捕魚，見公魚陪伴受鉤母魚而放鬆鬥志，反省把岸上的鬥爭習性帶入海洋。故強調情感、忠誠與人類態度的 D 合適。","solution":"甲由楊天一轉述，鼠最後取回同伴屍體；乙是敘事者捕魚，見公魚陪伴受鉤母魚而放鬆鬥志，反省把岸上的鬥爭習性帶入海洋。故強調情感、忠誠與人類態度的 D 合適。","common_errors":"不能把陪伴誤說成公魚成功救出母魚。","option_analysis":["甲不是作者親眼所見。","甲同伴已死，乙也未寫成功救出。","甲未主張人比鼠更有義。","乙由魚情反省人類捕獵心態。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q21","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":21,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":6,"source_pages":[6],"group_id":null,"stem":"下列各組「」內的同音字，字形完全不同的是：","options":["揶「ㄩˊ」他人╱「ㄩˊ」越規定╱覬「ㄩˊ」權位","阿「ㄩˊ」奉承╱膏「ㄩˊ」之地╱須「ㄩˊ」片刻","穿「ㄙㄨㄛ」其間╱日月如「ㄙㄨㄛ」╱教「ㄙㄨㄛ」","鉅細「ㄇㄧˇ」遺╱所向披「ㄇㄧˇ」╱奢「ㄇㄧˇ」","阻「ㄌㄢˊ」╱夜「ㄌㄢˊ」人靜╱意興「ㄌㄢˊ」珊"],"answer":{"indices":[0,1]},"printed_answer":"AB","answer_match":true,"primary_unit":"同音異字","skill_tags":["同音異字"],"explanation":{"schema":"explanation-v2","concept":"同音異字","key_insight":"填回每一組注音，檢查三格是否兩兩不同。","reasoning":"A 為揶揄、逾越、覬覦，三字是揄、逾、覦；B 為阿諛、膏腴、須臾，三字是諛、腴、臾，所以選 AB。C 的穿梭、日月如梭重複梭；D 的披靡、奢靡重複靡；E 的夜闌、意興闌珊重複闌。","solution":"A 為揶揄、逾越、覬覦，三字是揄、逾、覦；B 為阿諛、膏腴、須臾，三字是諛、腴、臾，所以選 AB。C 的穿梭、日月如梭重複梭；D 的披靡、奢靡重複靡；E 的夜闌、意興闌珊重複闌。","common_errors":"題目要字形全不同，同音只是給出要填的音。","option_analysis":["揄、逾、覦三字不同。","諛、腴、臾三字不同。","梭重複。","靡重複。","闌重複。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q22","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":22,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":6,"source_pages":[6],"group_id":null,"stem":"下列各組「」內的詞，意義前後相同的是：","options":["「微」行，入古寺╱引入，「微」指左公處","猶「且」從師而問焉╱聞左公被炮烙，旦夕「且」死","不拘於時，請學「於」余╱持五十金，涕泣謀「於」禁卒","即解貂覆生，「為」掩戶╱背筐，手長鑱，「為」除不潔者","今其智「乃」反不能及╱公辨其聲，而目不可開，「乃」奮臂以指撥眥"],"answer":{"indices":[0,2]},"printed_answer":"AC","answer_match":true,"primary_unit":"文言虛實詞","skill_tags":["文言虛實詞"],"explanation":{"schema":"explanation-v2","concept":"文言虛實詞","key_insight":"把每組相同字譯成白話後比較功能。","reasoning":"校方標 AC。「微行」是不公開行蹤地行走，「微指」是暗暗指示；兩處微都含隱蔽、輕微動作。「請學於余」和「謀於禁卒」的於都引介求教、商議的對象。B 的且分別是尚且與將要；D 為的施事方向須逐句核；E 的乃分別是竟與才。","solution":"校方標 AC。「微行」是不公開行蹤地行走，「微指」是暗暗指示；兩處微都含隱蔽、輕微動作。「請學於余」和「謀於禁卒」的於都引介求教、商議的對象。B 的且分別是尚且與將要；D 為的施事方向須逐句核；E 的乃分別是竟與才。","common_errors":"不要只看「為」和「於」都像介詞，需帶回上下文。","option_analysis":["兩處微皆指暗中、不顯露。","尚且與將要不同。","於都引介相對人。","兩處為需辨施事／受事，不可只看字面。","竟然與才、於是不同。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q24","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":24,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":6,"source_pages":[6],"group_id":null,"stem":"臺灣現代詩壇曾提出「縱的傳承」（承襲中國傳統，與古典詩歌、典故、題材的延續有關）、「橫的移植」（借用、轉化西方的意象、形式、哲學或故事）的主張，判斷下列詩句屬於「縱的傳承」的是：","options":["我乃曠野裡獨來獨往的一匹狼／不是先知／沒有半個字的嘆息","你曾是黃河之水天上來／陰山動／龍門開／而今黃河反從你的句中來／驚濤與豪笑／萬里滔滔入海","輕拍了一下／沉重的生命浮了上來／那渾熟堅實的圓／這一圈走完，還有另外一圈／時間的跑道，光的競技場／失盾的薛西佛斯","博浪沙，天色還未明／橋上正候著那褐衣的老人／鞋踢在橋下，兵書揣在懷裡／說星羅一天，棋布滿地／這一局陰幢幢的長夜一過／贏家的棋變輸家的棋","時間七月七日／地點長生殿／一個高瘦如青衫男子／一個沒有臉孔的女子／火焰繼續升起／白包如空氣中／一雙翅膀／又／一雙翅膀／飛入殿外的月色"],"answer":{"indices":[1,3,4]},"printed_answer":"BDE","answer_match":true,"primary_unit":"現代詩典故","skill_tags":["現代詩典故"],"explanation":{"schema":"explanation-v2","concept":"現代詩典故","key_insight":"檢查古典詩句、歷史人物與西方神話線索。","reasoning":"B 化用李白「黃河之水天上來」，D 的博浪沙及橋上老人指張良與黃石公典故，E 的七月七日、長生殿出自唐玄宗與楊貴妃故事，皆承接中國傳統，選 BDE。C 的薛西佛斯出自希臘神話，A 未具此題要求的中國古典承襲線索。","solution":"B 化用李白「黃河之水天上來」，D 的博浪沙及橋上老人指張良與黃石公典故，E 的七月七日、長生殿出自唐玄宗與楊貴妃故事，皆承接中國傳統，選 BDE。C 的薛西佛斯出自希臘神話，A 未具此題要求的中國古典承襲線索。","common_errors":"詩句寫中文或黃河，不足以自動判縱向承襲；需找具體典故。","option_analysis":["缺明確古典承繼依據。","直接轉化李白詩句。","薛西佛斯為西方神話。","博浪沙與黃石公典故。","長生殿、七夕取中國典故。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","modern_text_rights_review_required"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q25","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":25,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":6,"source_pages":[6],"group_id":null,"stem":"下列關於〈左忠毅公逸事〉一文的用字分析，詮釋適當的是：","options":["及試，吏呼名，至史公，公「瞿然注視」：左公確認人才之後的驚喜","及左公下廠獄，史朝夕「窺」獄門外：暗示宦官防伺甚嚴，不易靠近","引入，「微」指左公處：廠衛防範甚嚴，史公乃偽裝而入，故不宜明指","史前跪，抱公膝而「嗚咽」：史公壓抑情感僅低聲哭泣，唯恐驚動他人","因「摸」地上刑械，作投擊勢：左公不欲引起獄中騷動，避免器械碰撞"],"answer":{"indices":[0,1,2,3]},"printed_answer":"ABCD","answer_match":true,"primary_unit":"文言動作描寫","skill_tags":["文言動作描寫"],"explanation":{"schema":"explanation-v2","concept":"文言動作描寫","key_insight":"讀字詞前後發生的事，檢查心理推論有無依據。","reasoning":"校方標 ABCD。左公「瞿然注視」呈驚喜重視；史可法在獄門外「窺」顯戒備；入獄後「微」指而不明說；跪抱嗚咽寫情緒受抑。E 左公摸刑械是作投擊勢驅逐史可法，並非怕器械撞擊，故不選。D 的「唯恐驚動」是推測，發布前宜再核對文本。","solution":"校方標 ABCD。左公「瞿然注視」呈驚喜重視；史可法在獄門外「窺」顯戒備；入獄後「微」指而不明說；跪抱嗚咽寫情緒受抑。E 左公摸刑械是作投擊勢驅逐史可法，並非怕器械撞擊，故不選。D 的「唯恐驚動」是推測，發布前宜再核對文本。","common_errors":"動作的原因須由情境證實，不能見「摸」便說是求安靜。","option_analysis":["辨才時震動注視。","獄門防範，難以接近。","秘密指認，避免暴露。","嗚咽寫低聲哽咽；動機仍需審閱。","摸刑械為投擊，不是避免聲響。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","explanation_inference_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q26","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":26,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":6,"source_pages":[6],"group_id":null,"stem":"人物描寫常藉由動作、外表或語言來呈現，以建構出飽滿的人物形象。關於下列文句畫雙線處的說明適當的是：7","options":["魏武謂脩曰：「解不？」答曰：「解。」魏武曰：「卿未可言，待我思之。」→顯示出曹操的不服輸及好勝心理","（魏武）乃嘆曰：「我才不及卿，乃覺三十里。」→以素以文才自詡的曹操也對楊脩甘拜下風，更凸顯楊脩才氣之高","公辨其聲，而目不可開，乃奮臂以指撥眥，目光如炬→表現左公意志堅強，即使被折磨得不成人樣，精神仍剛直不屈","（史可法）後常流涕述其事以語人曰：「吾師肺肝，皆鐵石所鑄造也！」→以史公之語陳述左公冷酷無情、鐵石心腸","兄子胡兒曰：「撒鹽空中差可擬。」兄女曰：「未若柳絮因風起。」→謝道韞文思及心性溫婉，不如男子的英姿颯爽"],"answer":{"indices":[0,1,2]},"printed_answer":"ABC","answer_match":true,"primary_unit":"人物刻畫","skill_tags":["人物刻畫"],"explanation":{"schema":"explanation-v2","concept":"人物刻畫","key_insight":"辨曹操對楊脩的先競後服及左公的精神。","reasoning":"曹操先要楊脩暫不說破，顯示他也要思索；後自嘆才不及卿，凸顯楊脩敏捷；左公受酷刑仍撥開眼瞼直視，顯堅毅，所以選 ABC。D 的鐵石肺肝是意志與忠義，並非冷酷；E 的謝道韞以柳絮比雪展才思，不能推她不如男性。","solution":"曹操先要楊脩暫不說破，顯示他也要思索；後自嘆才不及卿，凸顯楊脩敏捷；左公受酷刑仍撥開眼瞼直視，顯堅毅，所以選 ABC。D 的鐵石肺肝是意志與忠義，並非冷酷；E 的謝道韞以柳絮比雪展才思，不能推她不如男性。","common_errors":"「鐵石」比喻意志，不等於人格無情。","option_analysis":["曹操仍要自己思索。","自嘆不及襯楊脩之才。","受刑仍強撐直視。","鐵石指剛強非冷酷。","謝道韞的才思不可如此貶抑。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q27","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":27,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":7,"source_pages":[7],"group_id":null,"stem":"關於〈再別康橋〉的詩意與分析，下列敘述適當的是：","options":["「我輕輕的招手，／作別西天的雲彩」，以雲彩象徵因離別而興發的聚散無常之感","「在康河的柔波裡，／我甘心做一條水草」，表達願化為水草，流露對康橋的眷戀","「揉碎在浮藻間，／沉澱著彩虹似的夢」，以彩虹似的夢說明康河雨後優美的景致","「夏蟲也為我沉默，／沉默是今晚的康橋」，將情感投射於夏蟲，表現離別的惆悵","善用富色彩的詞彙，如「金柳」、「青荇」、「斑斕」，展現新月派繪畫美的特色"],"answer":{"indices":[1,3,4]},"printed_answer":"BDE","answer_match":true,"primary_unit":"詩歌意象","skill_tags":["詩歌意象"],"explanation":{"schema":"explanation-v2","concept":"詩歌意象","key_insight":"分辨景物、象徵與情感投射的層次。","reasoning":"康河水草表願長留康橋，夏蟲沉默映照離別惆悵，金柳、青荇、斑斕具色彩與新月派繪畫美，選 BDE。彩虹似的夢是心中理想，不是雨後自然景象；首段作別雲彩不等於把雲彩明指聚散無常。","solution":"康河水草表願長留康橋，夏蟲沉默映照離別惆悵，金柳、青荇、斑斕具色彩與新月派繪畫美，選 BDE。彩虹似的夢是心中理想，不是雨後自然景象；首段作別雲彩不等於把雲彩明指聚散無常。","common_errors":"意象可承載情感，不能把所有景物一律寫成抽象人生哲理。","option_analysis":["未具體把雲彩說成聚散無常。","願化水草寄眷戀。","彩虹夢偏理想追憶。","夏蟲沉默是情感投射。","色彩詞構成畫面。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","modern_text_rights_review_required"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q28","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":28,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":7,"source_pages":[7],"group_id":null,"stem":"閱讀徐志摩對美國和康橋生活的自述，選出符合原文的敘述（可複選）。作者說在美國兩年，忙於上課、聽講、考卷與娛樂；他覺得那段經驗沒有令自己開竅。到了康橋兩年，他常散步、划船、騎車、閒談、閱讀，認為康橋喚醒了他的求知欲、視野與自我意識，並讓他察覺自己先前的蒙昧。","options":["美國的生活充斥著忙碌的、制式化的學術要求與娛樂活動","美國的生活訓練作者的謀生能力，成為在英國生活的基礎","康橋的生活是主動、閒適的，更注重自我探索與心靈滋養","在美國功利性的學習無法帶來精神上的開竅與自我的覺醒","強調學習藝術與文學才能真正通竅，在美國時只是個草包"],"answer":{"indices":[0,2,3]},"printed_answer":"ACD","answer_match":true,"primary_unit":"作者生活比較","skill_tags":["作者生活比較"],"explanation":{"schema":"explanation-v2","concept":"作者生活比較","key_insight":"把美國與康橋經驗及自我覺醒一一對照。","reasoning":"作者寫美國上課考卷與娛樂活動繁忙，康橋散步划船與閒談則開啟眼睛、求知慾及自我意識，所以 A、C、D 合於文本。文章沒有說美國生活養成謀生技能，也不主張只有藝術文學可通竅。","solution":"作者寫美國上課考卷與娛樂活動繁忙，康橋散步划船與閒談則開啟眼睛、求知慾及自我意識，所以 A、C、D 合於文本。文章沒有說美國生活養成謀生技能，也不主張只有藝術文學可通竅。","common_errors":"此段是作者自述，不可提升成所有人的普遍因果。","option_analysis":["美國經驗以課業、娛樂活動為主。","未提謀生訓練。","康橋啟動自我探索。","作者認為美國未使自己通竅。","未限定真正學習只有藝術文學。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","modern_text_rights_review_required"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"platform_context_with_original_options","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q29","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":29,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":7,"source_pages":[7],"group_id":null,"stem":"〈鬼頭刀〉一文中有許多捕魚過程與描繪魚類的敘述。下列文句詮釋適當的是：","options":["「海豚會跟著船筏的轉彎而轉彎，仍舊與船筏保持一定的距離在船舷邊跳躍。再把舵搖向另一個方向，讓船筏快速離開，牠們立刻又跟了上來，始終與我們保持一段安全距離。」：暗示人類的殺戮使海豚無法完全信任人類","「牠的價值表現在牠的生命上，就像牠美麗的色彩與藍色星點，在離開海洋離開生命後，即刻消逝。」：鬼頭刀的價值是在美麗的色彩和藍色的星點，若缺乏這兩種條件，就在市場上賣不到好價錢","「一條大魚咬中了船尾拖釣的假餌，八十磅的粗線及緩衝用的內胎橡皮瞬間被拉成筆直，時空似乎凍結住了，就等候斷裂的一聲巨響。」：暗示大魚力大無比，奮力掙脫的氣勢，對比出漁人措手不及的驚慌，以及預期會被魚兒掙脫的心理","「在我的夢裡，開始出現了跟鬼頭刀搏鬥的場景，那倨傲桀驁的眼神經常壓迫著我的夢，一遍又一遍，我撫摸著銳利的魚鉤，一遍又一遍把鮮豔的假餌提在眼前晃動。我常常幻覺進入鬼頭刀牠的眼、牠的心，我終日沉浸悠游在藍色冰涼的海洋中，我看到船筏底部黑色的陰影在我頭上的海面光影中滑行而過，槳葉打出一團翻滾的白色泡沫。」：顯現鬼頭刀對漁人的挑戰與威脅，及作者內心的激昂鬥志","「一個個餌鉤沉下水面，就像沉下一個個倒懸的問號，而答案往往是從零到無窮，甚或常常連問號也無法收回。」：表示漁人捕魚和魚逃逸之間的鬥智鬥力，是場無盡的戰爭，亦是生物與人彼此的生存競爭"],"answer":{"indices":[0,2,3,4]},"printed_answer":"ACDE","answer_match":true,"primary_unit":"敘事與意象","skill_tags":["敘事與意象"],"explanation":{"schema":"explanation-v2","concept":"敘事與意象","key_insight":"把魚的生命價值、人的獵捕心理與敘事語氣分開。","reasoning":"校方標 ACDE。海豚與船保持距離、粗線繃緊、鬼頭刀反覆入夢與餌鉤如問號，分別呈現警戒、力量、較勁及捕獲不確定性；B 把魚活著才有的美與生命價值說成市場售價，違背文章主題。A、E 的因果與比喻帶有延伸推論，仍待人工以全文語境審閱。","solution":"校方標 ACDE。海豚與船保持距離、粗線繃緊、鬼頭刀反覆入夢與餌鉤如問號，分別呈現警戒、力量、較勁及捕獲不確定性；B 把魚活著才有的美與生命價值說成市場售價，違背文章主題。A、E 的因果與比喻帶有延伸推論，仍待人工以全文語境審閱。","common_errors":"作者強調生命不可僅用商品價格衡量。","option_analysis":["可讀出對人類的警戒，惟推論待核。","生命價值不是售價。","線緊顯魚力與漁人危機感。","夢境展現搏鬥期待。","餌鉤問號凸顯未知與人魚角力。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","modern_text_rights_review_required","explanation_inference_needs_review"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q30","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":30,"questionType":"multiple_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":7,"source_pages":[7,8],"group_id":null,"stem":"比較甲、乙兩文，選適當說明。甲〈斷章〉以橋上行人、樓上看風景者、窗前明月與他人的夢，讓觀看者也成為他人眼中的風景；乙是網路創作中的第一人稱敘事者單方面傾慕「你」，自己的視聽只為對方，對方卻可能望向別處，如鏡子只映出自己，敘事者不責怪對方，承認每人視線與夢境不同。","options":["甲文藉「橋」、「樓」、「窗子」等具體空間，形成不同視角的觀看","甲文由虛而實，藉「裝飾」夢境表現個體存在對於他人無意識的美化","乙文藉由「對著一面鏡子傾訴」的譬喻，表達人際關係的雙向與對等","甲文採第二人稱視角，情感較客觀；乙文採第一人稱視角，情感較主觀真切","兩文均以「觀看」與「被觀看」為核心，探討人我互動主體與客體的相對性"],"answer":{"indices":[0,3]},"printed_answer":"AD","answer_match":true,"primary_unit":"跨文本觀看","skill_tags":["跨文本觀看"],"explanation":{"schema":"explanation-v2","concept":"跨文本觀看","key_insight":"先檢查敘事人稱及觀看是否相互，再查未明言的象徵。","reasoning":"甲以橋、樓、窗子切換觀察位置，乙用「我」述說對「你」的單向愛慕，語氣較主觀，因此 A、D。B 把甲的景象次序說成由虛而實，實際先具體場景後夢境；C 把乙未得到回望的情感寫成對等；E 將兩文都解成相同的主客互換，乙並無此互換。","solution":"甲以橋、樓、窗子切換觀察位置，乙用「我」述說對「你」的單向愛慕，語氣較主觀，因此 A、D。B 把甲的景象次序說成由虛而實，實際先具體場景後夢境；C 把乙未得到回望的情感寫成對等；E 將兩文都解成相同的主客互換，乙並無此互換。","common_errors":"同有「看」字不等於兩篇都表達相互觀看。","option_analysis":["橋樓窗構成不同視角。","甲先實景後夢境。","乙強調單向不對等。","甲第二人稱、乙第一人稱。","乙沒有甲式的主客互換。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","modern_text_rights_review_required"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"platform_context_with_original_options","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q31","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":31,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":8,"source_pages":[8],"group_id":"cksh-114-1-1-g1-chinese-q31-32","stem":"依據甲、乙二文，下列解讀最適當的是：（占2分，單選題）","options":["甲文作者認為詩的語言來自尋常生活，自然使用日常文字即能完成上乘詩作","乙文作者強調現代詩必須營造栩栩如生的奇特情境，否則會流於陳腐、空泛","二文皆呼籲詩人在創作時須以旁觀的角度來檢視，以避免詩作陷入主觀偏狹","二文皆將詩的語言視為可以鎔鑄與創造的材料，並賦予語言新的價值與意義"],"answer":{"index":3},"printed_answer":"D","answer_match":true,"primary_unit":"現代詩比較","skill_tags":["現代詩比較"],"explanation":{"schema":"explanation-v2","concept":"現代詩比較","key_insight":"抓甲鍊金與乙馭劍兩個譬喻的共同作用。","reasoning":"甲用日常語言為材料，需詩人有意志地提鍊；乙要求意象與整體情境融合，而不是扭曲字句求新。兩文都把語言視為可以經由創作轉化、產生新價值的材料，故 D。A 忽略「創造」，B 誤說一定要奇特，C 把自覺反省誤成旁觀視角。","solution":"甲用日常語言為材料，需詩人有意志地提鍊；乙要求意象與整體情境融合，而不是扭曲字句求新。兩文都把語言視為可以經由創作轉化、產生新價值的材料，故 D。A 忽略「創造」，B 誤說一定要奇特，C 把自覺反省誤成旁觀視角。","common_errors":"用尋常文字不是自然拼湊便能成詩。","option_analysis":["仍須意志與提鍊。","乙求意象和諧，不強調奇特。","反省創作不等於旁觀自己。","兩文都寫轉化語言創造詩意。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q32","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":32,"questionType":"short_answer","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":8,"source_pages":[8],"group_id":"cksh-114-1-1-g1-chinese-q31-32","stem":"甲、乙文分別以「鍊金術」「馭劍術」說明現代詩創作。請在下列架構填①②③：\n甲：詩人特質＝意志力；設喻＝鍊金術；喻意說明＝③（30字內）。\n乙：詩人特質＝①（10字內）；設喻＝②（10字內）；喻意說明＝意象須與詩人及整體情境合一。","options":[],"answer":{"grading":"manual_required","reference":"自覺力與反省力；馭劍術；提鍊平庸、廉價、無聊的日常語言，變造出閃閃發光的詩作"},"printed_answer":null,"answer_match":true,"primary_unit":"混合題填表","skill_tags":["混合題填表"],"explanation":{"schema":"explanation-v2","concept":"混合題填表","key_insight":"分別從甲乙找原文特質、設喻及譬喻對應動作。","reasoning":"①乙說詩人須具自覺力與反省力。②乙將創作意象比作馭劍術，貴在身劍合一。③甲說以日常語言為材料，提鍊平庸廉價的語言成為質純美好的詩作。應依原卷表格按①②各十字、③三十字上限填寫。","solution":"①乙說詩人須具自覺力與反省力。②乙將創作意象比作馭劍術，貴在身劍合一。③甲說以日常語言為材料，提鍊平庸廉價的語言成為質純美好的詩作。應依原卷表格按①②各十字、③三十字上限填寫。","common_errors":"不要將甲的意志力誤填到乙，也不可把「馭劍術」只解作技巧炫目而漏整體情境。","option_analysis":[],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed","visual_layout_review_required","manual_grading_required"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"platform_context_with_original_options","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q33","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":33,"questionType":"short_answer","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":9,"source_pages":[9],"group_id":"cksh-114-1-1-g1-chinese-q33-34","stem":"依共用的〈傷仲永〉與〈逆旅小子〉填答：①以自己的話寫逆旅小子的外貌／衣著（10字內）；②從乙文抄錄叔父虐待他的原句（20字內）；③以自己的話寫出能防止仲永才情泯滅的策略（10字內）；另回答兩人的主要照顧者這樣對待他們的共同動機（10字內）。","options":[],"answer":{"grading":"manual_required","reference":"身體瘦弱、衣著單薄；不恤其寒飢而苦役之；夜則閉之戶外；接受教育；都為了自身錢財利益"},"printed_answer":null,"answer_match":true,"primary_unit":"文言跨文本比較","skill_tags":["文言跨文本比較"],"explanation":{"schema":"explanation-v2","concept":"文言跨文本比較","key_insight":"依表格先找外貌與虐待原句，再找作者提出的外在援助。","reasoning":"(1) ①逆旅小子瘦弱，衣著單薄。②可抄乙「不恤其寒飢而苦役之；夜則閉之戶外」。③仲永若能持續接受教育，才不至於天賦泯滅。(2) 父親以仲永才能換錢，叔父為免孩子長大分產而虐待，兩人都逐私利、貪圖財產。作答仍須依卷面各格限字、抄錄要求核查。","solution":"(1) ①逆旅小子瘦弱，衣著單薄。②可抄乙「不恤其寒飢而苦役之；夜則閉之戶外」。③仲永若能持續接受教育，才不至於天賦泯滅。(2) 父親以仲永才能換錢，叔父為免孩子長大分產而虐待，兩人都逐私利、貪圖財產。作答仍須依卷面各格限字、抄錄要求核查。","common_errors":"①與③題目要求不可抄原文，②反而要求抄乙文；不能顛倒。","option_analysis":[],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed","visual_layout_review_required","manual_grading_required"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"platform_context_with_original_options","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false},{"id":"cksh-114-1-1-g1-chinese-q34","subject":"chinese","variant":"國綜","school":"成功高中","grade":1,"academic_year":114,"semester":1,"exam":1,"question_number":34,"questionType":"single_choice","sourceType":"school_official","sourceId":"cksh-114-1-1-g1-chinese","source_title":"114 學年度上學期高一國文第一次期中考解析卷","source_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_url":"https://www.cksh.tp.edu.tw/wp-content/uploads/doc/cg501/114-1-1%E9%AB%98%E4%B8%80%E5%9C%8B%E7%B6%9C%E8%A9%A6%E9%A1%8C.pdf","answer_source":"試卷逐題印出的答案；另行公布的高一解答壓縮檔未含國文科","review_evidence_urls":[],"source_page":9,"source_pages":[9],"group_id":"cksh-114-1-1-g1-chinese-q33-34","stem":"〈傷仲永〉與〈逆旅小子〉二文雖題材不同，但都反映了社會問題。下列敘述不適當的是：（占2分，單選題）","options":["〈傷仲永〉以「幼時神童、成年平庸」形成反差，敘述天資消逝","〈逆旅小子〉以「少時受虐、次年死去」呈現弱小者悲慘的命運","〈傷仲永〉顯見親情鄰里的溫暖，〈逆旅小子〉則見鄰里的冷漠","二文皆揭示幼孩若缺乏外在支持，天資或生命終難以維持的道理"],"answer":{"index":2},"printed_answer":"C","answer_match":true,"primary_unit":"跨文本社會問題","skill_tags":["跨文本社會問題"],"explanation":{"schema":"explanation-v2","concept":"跨文本社會問題","key_insight":"分辨敘事中誰得利益，以及鄰里與官府實際作為。","reasoning":"〈傷仲永〉寫神童被父親帶著四處拜訪求利、不使學而終泯然；〈逆旅小子〉寫受叔父虐待、作者曾書告官府，仍無人查問而死。因此 C 說甲有親情鄰里溫暖、乙特別揭露鄰里冷漠，均缺乏文本支持，是不適當項。兩文都強調孩子需要教育、照護或公權力援助。","solution":"〈傷仲永〉寫神童被父親帶著四處拜訪求利、不使學而終泯然；〈逆旅小子〉寫受叔父虐待、作者曾書告官府，仍無人查問而死。因此 C 說甲有親情鄰里溫暖、乙特別揭露鄰里冷漠，均缺乏文本支持，是不適當項。兩文都強調孩子需要教育、照護或公權力援助。","common_errors":"不要把邑人邀請仲永的好奇與付錢，誤認為保護兒童的溫暖。","option_analysis":["天才泯滅形成反差。","小子受虐至死屬悲劇。","兩文不是如此對比鄰里溫情。","缺外部支持是共同警示。"],"strategy":"回到校方原卷及題組脈絡逐項核對；有疑義的卷面答案須先複核。","explanation_status":"draft_review_required"},"explanation_source":"platform_authored","explanation_status":"draft_review_required","review_flags":["paraphrased_wording_needs_review","explanation_draft_needs_review","group_context_not_transcribed"],"parse_confidence":0.8,"classification_confidence":0.6,"wording_status":"source_question_transcribed","content_capture_status":"inline_question_original_option_order","sync_status":"disabled_pending_review","published":false}]};})(window);
